package com.mentality.forgewebmap.player;
import org.junit.jupiter.api.Test; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
class PlayerMarkerServiceTest { @Test void playerSnapshotPublicationIsImmutable(){PlayerMarkerService s=new PlayerMarkerService();var src=new ArrayList<>(List.of(new PlayerMarkerService.PlayerInfo("n","d",1,2,3,4)));s.publish(src);src.clear();assertEquals(1,s.getPlayers().size());assertThrows(UnsupportedOperationException.class,()->s.getPlayers().clear());}@Test void playerMarkersDisabledClearsSnapshot(){PlayerMarkerService s=new PlayerMarkerService();s.publish(List.of(new PlayerMarkerService.PlayerInfo("n","d",1,2,3,4)));s.setEnabled(false);assertTrue(s.getPlayers().isEmpty());}@Test void playerMarkersReenableDoesNotRestoreStaleSnapshot(){PlayerMarkerService s=new PlayerMarkerService();s.publish(List.of(new PlayerMarkerService.PlayerInfo("n","d",1,2,3,4)));s.setEnabled(false);s.setEnabled(true);assertTrue(s.getPlayers().isEmpty());}}
